package org.eclipse.rdf4j.sail.base;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.doThrow;
import static org.mockito.Mockito.mock;

import java.util.Set;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;

import org.eclipse.rdf4j.common.iteration.CloseableIteration;
import org.eclipse.rdf4j.query.Query;
import org.eclipse.rdf4j.sail.helpers.AbstractSail;
import org.junit.jupiter.api.Test;

class SlowQueryLoggingIterationTest {

	@Test
	void closingFailureIsPreservedWhenCompletionLoggingIsDisabled() {
		assertClosingFailureIsPreserved(0L);
	}

	@Test
	void closingFailureIsPreservedWhenCompletionThresholdIsNotExceeded() {
		assertClosingFailureIsPreserved(2L);
	}

	private void assertClosingFailureIsPreserved(long thresholdSeconds) {
		CloseableIteration<Object> delegate = mock(CloseableIteration.class);
		IllegalStateException failure = new IllegalStateException("close failed");
		doThrow(failure).when(delegate).close();
		SlowQueryLoggingIteration<Object> iteration = new SlowQueryLoggingIteration<>(delegate,
				mock(AbstractSail.class),
				info(thresholdSeconds), new SlowQueryLogFormatter(), -1_000L);

		assertThatThrownBy(iteration::close).isSameAs(failure);
	}

	@Test
	void overlappingCompletionCallbacksCloseAndLogOnlyOnce() throws Exception {
		CloseableIteration<Object> delegate = mock(CloseableIteration.class);
		CountDownLatch firstCloseEntered = new CountDownLatch(1);
		CountDownLatch releaseFirstClose = new CountDownLatch(1);
		AtomicInteger closes = new AtomicInteger();
		AtomicInteger completionEntries = new AtomicInteger();
		doAnswer(invocation -> {
			if (closes.incrementAndGet() == 1) {
				firstCloseEntered.countDown();
				assertThat(releaseFirstClose.await(10, TimeUnit.SECONDS)).isTrue();
			}
			return null;
		}).when(delegate).close();
		SlowQueryLogFormatter formatter = new SlowQueryLogFormatter() {
			@Override
			String formatExecution(SlowQueryLogInfo info, long elapsedMillis) {
				completionEntries.incrementAndGet();
				return "completed";
			}
		};
		SlowQueryLoggingIteration<Object> iteration = new SlowQueryLoggingIteration<>(delegate,
				mock(AbstractSail.class),
				info(1L), formatter, -2_000L);

		try (var executor = Executors.newFixedThreadPool(2)) {
			// Model overlapping callbacks permitted by the non-atomic close guard in IterationWrapper's superclass.
			var firstClose = executor.submit(iteration::handleClose);
			try {
				assertThat(firstCloseEntered.await(10, TimeUnit.SECONDS)).isTrue();
				executor.submit(iteration::handleClose).get(10, TimeUnit.SECONDS);
			} finally {
				releaseFirstClose.countDown();
			}
			firstClose.get(10, TimeUnit.SECONDS);
		}

		assertThat(closes).hasValue(1);
		assertThat(completionEntries).hasValue(1);
	}

	private SlowQueryLogInfo info(long thresholdSeconds) {
		return new SlowQueryLogInfo("test.Sail", thresholdSeconds, 0L, Query.QueryType.TUPLE,
				"SELECT * WHERE { ?s ?p ?o }", null, null, null, Set.of());
	}
}
